import{_ as o,o as l,c as i,ae as a}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"iCost 帳單匯入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/08-icost-bill-import-guide.md","filePath":"v1/zh-HK/guide/08-icost-bill-import-guide.md"}'),e={name:"v1/zh-HK/guide/08-icost-bill-import-guide.md"};function r(d,t,s,n,h,c){return l(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="icost-帳單匯入指南" tabindex="-1">iCost 帳單匯入指南 <a class="header-anchor" href="#icost-帳單匯入指南" aria-label="Permalink to &quot;iCost 帳單匯入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本指南將指引你如何從 <strong>iCost</strong> 匯出帳單，並匯入到 <strong>考拉記帳</strong> App。</p><p>考拉記帳目前支援匯入 <strong>iCost 匯出的 Excel 檔</strong>（<code>.xlsx</code> / <code>.xls</code>），並且 <strong>不支援 iCost 的 CSV 檔</strong>。</p><hr><h2 id="📱-第一步-在-icost-中匯出帳單" tabindex="-1">📱 第一步：在 iCost 中匯出帳單 <a class="header-anchor" href="#📱-第一步-在-icost-中匯出帳單" aria-label="Permalink to &quot;📱 第一步：在 iCost 中匯出帳單&quot;">​</a></h2><p>不同版本的 iCost 入口可能略有差異，但思路一致：進入「匯出/資料匯出」，選擇匯出格式為 Excel 後保存檔案。</p><h3 id="步驟-1-進入匯出入口" tabindex="-1">步驟 1：進入匯出入口 <a class="header-anchor" href="#步驟-1-進入匯出入口" aria-label="Permalink to &quot;步驟 1：進入匯出入口&quot;">​</a></h3><ol><li>打開 <strong>iCost</strong></li><li>進入 <strong>設定 / 更多</strong>（或「我的」頁中的設定入口）</li><li>找到 <strong>匯出 / 資料匯出 / 匯出帳單</strong>（名稱可能略有不同）</li></ol><h3 id="步驟-2-選擇匯出格式" tabindex="-1">步驟 2：選擇匯出格式 <a class="header-anchor" href="#步驟-2-選擇匯出格式" aria-label="Permalink to &quot;步驟 2：選擇匯出格式&quot;">​</a></h3><ol><li>匯出格式選 <strong>Excel（.xlsx / .xls）</strong></li><li>選擇匯出時間範圍（建議每次不超過 3 個月）</li><li>匯出並保存到本機（或透過「分享/保存到檔案」）</li></ol><blockquote><p>⚠️ <strong>重要</strong>：若匯出為 CSV，考拉記帳會提示「不支援 CSV，請使用 Excel」。</p></blockquote><hr><h2 id="📱-第二步-在考拉記帳中匯入" tabindex="-1">📱 第二步：在考拉記帳中匯入 <a class="header-anchor" href="#📱-第二步-在考拉記帳中匯入" aria-label="Permalink to &quot;📱 第二步：在考拉記帳中匯入&quot;">​</a></h2><h3 id="步驟-1-進入匯入頁面" tabindex="-1">步驟 1：進入匯入頁面 <a class="header-anchor" href="#步驟-1-進入匯入頁面" aria-label="Permalink to &quot;步驟 1：進入匯入頁面&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊底部導覽列 <strong>「設定」</strong></li><li>在設定頁找到 <strong>「帳單匯入」</strong></li><li>點擊進入帳單匯入頁</li></ol><h3 id="步驟-2-選擇匯入來源" tabindex="-1">步驟 2：選擇匯入來源 <a class="header-anchor" href="#步驟-2-選擇匯入來源" aria-label="Permalink to &quot;步驟 2：選擇匯入來源&quot;">​</a></h3><ol><li>點擊 <strong>「匯入來源」</strong></li><li>在列表中選擇 <strong>「iCost」</strong></li></ol><blockquote><p>⚠️ <strong>重要</strong>：必須選擇「iCost」，否則系統會按其他來源解析，導致找不到表頭或欄位錯位。</p></blockquote><h3 id="步驟-3-選擇檔案" tabindex="-1">步驟 3：選擇檔案 <a class="header-anchor" href="#步驟-3-選擇檔案" aria-label="Permalink to &quot;步驟 3：選擇檔案&quot;">​</a></h3><ol><li>點擊 <strong>「檔案路徑」</strong></li><li>選擇 iCost 匯出的 <strong>Excel 檔</strong>（<code>.xlsx</code> / <code>.xls</code>）</li><li>確認檔名已顯示</li></ol><h3 id="步驟-4-關聯帳本" tabindex="-1">步驟 4：關聯帳本 <a class="header-anchor" href="#步驟-4-關聯帳本" aria-label="Permalink to &quot;步驟 4：關聯帳本&quot;">​</a></h3><ol><li>點擊 <strong>「關聯帳本」</strong></li><li>選擇匯入目標帳本</li><li>確認帳本選擇</li></ol><h3 id="步驟-5-解析並預覽" tabindex="-1">步驟 5：解析並預覽 <a class="header-anchor" href="#步驟-5-解析並預覽" aria-label="Permalink to &quot;步驟 5：解析並預覽&quot;">​</a></h3><ol><li>點擊右上角 <strong>「解析」</strong></li><li>解析成功後進入預覽頁</li><li>在預覽頁可編輯單筆的分類、帳戶、時間、金額、標籤、備註等，再執行匯入</li></ol><h3 id="步驟-6-匯入" tabindex="-1">步驟 6：匯入 <a class="header-anchor" href="#步驟-6-匯入" aria-label="Permalink to &quot;步驟 6：匯入&quot;">​</a></h3><ol><li>預覽確認無誤後點擊 <strong>「匯入」</strong></li><li>等待匯入完成</li></ol><hr><h2 id="📋-icost-帳單檔案格式說明-excel" tabindex="-1">📋 iCost 帳單檔案格式說明（Excel） <a class="header-anchor" href="#📋-icost-帳單檔案格式說明-excel" aria-label="Permalink to &quot;📋 iCost 帳單檔案格式說明（Excel）&quot;">​</a></h2><p>考拉記帳對 iCost Excel 的校驗點：</p><ul><li>Excel 需要存在可讀取的工作表</li><li>表頭行需要包含 <strong>「日期」</strong> 字樣（用於定位表頭行）</li></ul><blockquote><p>📝 <strong>提示</strong>：若 iCost 匯出可選語言，建議以中文表頭匯出（至少保證表頭行包含「日期」）。</p></blockquote><h3 id="讀取欄位-按列位置" tabindex="-1">讀取欄位（按列位置） <a class="header-anchor" href="#讀取欄位-按列位置" aria-label="Permalink to &quot;讀取欄位（按列位置）&quot;">​</a></h3><p>考拉記帳按列位置讀取 iCost Excel 的部分欄位，其他列會被忽略：</p><table tabindex="0"><thead><tr><th>欄序號</th><th>欄位</th><th>說明</th></tr></thead><tbody><tr><td>1</td><td>日期</td><td>支援 <code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> / <code>yyyy-MM-ddTHH:mm:ss</code> / <code>yyyy-MM-dd HH:mm:ss</code>；亦支援 Excel 序列號日期</td></tr><tr><td>2</td><td>類型</td><td>需包含「支出」或「收入」關鍵字；包含「支出」=支出，包含「收入」=收入</td></tr><tr><td>3</td><td>金額</td><td>允許帶 <code>+</code>/<code>-</code>，匯入會自動去除符號並去掉千分位逗號</td></tr><tr><td>4</td><td>父分類</td><td>用於匹配考拉記帳收支項目父類名稱</td></tr><tr><td>5</td><td>子分類</td><td>為空時會自動使用「父分類」的值</td></tr><tr><td>6</td><td>帳戶</td><td>為空時會使用預設帳戶作為兜底</td></tr><tr><td>8</td><td>備註</td><td>備註文字</td></tr><tr><td>9</td><td>幣種代碼</td><td>例如 <code>CNY</code> / <code>USD</code>；為空或匹配失敗時使用目標帳本幣種</td></tr><tr><td>10</td><td>標籤</td><td>多個標籤以逗號分隔（同時支援中文逗號 <code>，</code>）</td></tr></tbody></table><h3 id="匯入映射-考拉記帳" tabindex="-1">匯入映射（考拉記帳） <a class="header-anchor" href="#匯入映射-考拉記帳" aria-label="Permalink to &quot;匯入映射（考拉記帳）&quot;">​</a></h3><ul><li>日期（row[0]）→ 帳單日期</li><li>類型（row[1]）→ 帳單類型</li><li>金額（row[2]）→ 金額</li><li>一級分類（row[3]）→ 一級分類（並匹配/建立）</li><li>二級分類（row[4]，空則用一級）→ 二級分類（並匹配/建立）</li><li>帳戶（row[5]，空則預設帳戶）→ 帳戶</li><li>第 7 列（row[6]）→ 不入庫（未使用）</li><li>備註（row[7]）→ 備註</li><li>幣種代碼（row[8]）→ 幣種（按 code 匹配；失敗則用帳本幣種）</li><li>標籤（row[9]）→ 標籤（解析/建立後綁定）</li></ul><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><ol><li><strong>僅支援 Excel</strong>：iCost CSV 檔無法匯入。</li><li><strong>不自動去重</strong>：重複匯入同一份檔案會生成重複帳單，請避免多次匯入同一時間段。</li><li><strong>表頭語言</strong>：解析依賴表頭行包含「日期」；若匯出為非中文表頭，可能導致找不到表頭而解析失敗。</li><li><strong>帳戶為空的處理</strong>：若匯出中「帳戶」列為空，會使用預設帳戶兜底；建議在預覽頁統一修改，或在 iCost 匯出前補全帳戶資訊。</li><li><strong>收支項目匹配</strong>：按「父分類 + 子分類」匹配；匹配失敗會在預覽提示不完善，需要手動選擇後再匯入。</li></ol><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-提示「未找到-icost-帳單表頭」" tabindex="-1">Q1：提示「未找到 iCost 帳單表頭」？ <a class="header-anchor" href="#q1-提示「未找到-icost-帳單表頭」" aria-label="Permalink to &quot;Q1：提示「未找到 iCost 帳單表頭」？&quot;">​</a></h3><p>常見原因：</p><ol><li>Excel 表頭行不包含「日期」（例如匯出為英文表頭）</li><li>檔案不是 iCost 匯出的帳單檔，或二次編輯破壞了表結構</li><li>Excel 檔為空/沒有工作表</li></ol><p>建議重新從 iCost 匯出，並優先選擇中文表頭。</p><h3 id="q2-帳戶為空導致匯入後都進了同一個帳戶" tabindex="-1">Q2：帳戶為空導致匯入後都進了同一個帳戶？ <a class="header-anchor" href="#q2-帳戶為空導致匯入後都進了同一個帳戶" aria-label="Permalink to &quot;Q2：帳戶為空導致匯入後都進了同一個帳戶？&quot;">​</a></h3><p>這是正常兜底行為：當「帳戶」列為空時會使用預設帳戶。可在預覽頁批量編輯帳戶，或在 iCost 匯出前補全帳戶後再重新匯入。</p><h3 id="q3-分類匹配不上怎麼辦" tabindex="-1">Q3：分類匹配不上怎麼辦？ <a class="header-anchor" href="#q3-分類匹配不上怎麼辦" aria-label="Permalink to &quot;Q3：分類匹配不上怎麼辦？&quot;">​</a></h3><p>可在預覽頁進入單筆手動選擇收支項目；或先在考拉記帳建立與 iCost 匯出檔同名的收支項目後再重新解析。</p><hr><h2 id="📚-相關教學" tabindex="-1">📚 相關教學 <a class="header-anchor" href="#📚-相關教學" aria-label="Permalink to &quot;📚 相關教學&quot;">​</a></h2><ul><li><a href="./01-template-bill-import-guide">模板帳單匯入指南</a></li><li><a href="./02-wechat-bill-import-guide">微信帳單匯入教學</a></li><li><a href="./03-alipay-bill-import-guide">支付寶帳單匯入教學</a></li><li><a href="./07-pixiu-bill-import-guide">貔貅帳單匯入指南</a></li><li><a href="./04-multi-ledger-guide">多帳本功能說明</a></li></ul><hr><p><strong>最後更新</strong>：2026 年 4 月</p>',55)])])}const b=o(e,[["render",r]]);export{g as __pageData,b as default};
